        // throws a QueryCancelledException
        qIter.hasNext();
    } finally {
        //assertTrue(iterator.isCanceled()) ;
        assertEquals(500, iterator.getReturnedElementCount());
        assertEquals(0, DataBagExaminer.countTemporaryFiles(qIter.db));
        qIter.close();
    }
    assertEquals(0, DataBagExaminer.countTemporaryFiles(qIter.db));
}

