public void append_4() {
    List<String> L = new ArrayList<>(3);
    L.add("a");
    L.add("b");
    L.add("c");
    List<String> R = new ArrayList<>(3);
    R.add("d");
    R.add("e");
    R.add("f");
    Iterator<String> LR = Iter.append(L.iterator(), R.iterator());
    while (LR.hasNext()) {
        String s = LR.next();
        if ("c".equals(s)) {
            // test for JENA-60
            LR.hasNext();
            LR.remove();
        }
    }
    assertEquals("ab", Iter.asString(L, ""));
    assertEquals("def", Iter.asString(R, ""));
}

