    // Prepare a dataset
    Dataset ds = TestUtils.generateDataset(1, 1000, true);
    // Work with the connection
    JenaConnection conn = this.getConnection(ds);
    Statement stmt = conn.createStatement();
    // Set timeout to 1 second
    stmt.setQueryTimeout(1);
    try {
        ResultSet rset = stmt.executeQuery("SELECT * WHERE { " + (this.usesNamedGraphAsDefault() ? "GRAPH <" + this.getDefaultGraphName() + "> {" : "") + " ?a ?b ?c . ?d ?e ?f . ?g ?h ?i " + (this.usesNamedGraphAsDefault() ? "}" : "") + "}");
