    String f = "src/test/resources/test1/*.ttl";
    sm.addIncludes(f);
    sm.addExcludes("src/test/resources/test1/test1.ttl");
    List<String> s = sm.matchFileNames();
    assertNotNull(s);
    assertEquals(1, s.size());
    assertTrue(s.get(0).endsWith("test2.ttl"));
}

