@Test
public void testOpenQueryType() {
    eval = new MockSecurityEvaluator(true, true, true, true, true, true);
    setup();
    try {
        final String query = "prefix fn: <http://www.w3.org/2005/xpath-functions#>  " + " SELECT ?foo ?bar WHERE " + " { ?foo a <http://example.com/class> ; " + "?bar [] ." + "  } ";
        final QueryExecution qexec = QueryExecutionFactory.create(query, dataset);
        try {
            final ResultSet results = qexec.execSelect();
            int count = 0;
            for (; results.hasNext(); ) {
                count++;
                results.nextSolution();
            }
            Assert.assertEquals(8, count);
        } finally {
            qexec.close();
        }
    } finally {
        dataset.close();
    }
}

