    dataTurtle(ds, StrUtils.strjoinNL("PREFIX rdfs:   <http://www.w3.org/2000/01/rdf-schema#>", "[] a <http://example.org/Entity>; rdfs:label 'foo' ."));
    ds.begin(ReadWrite.READ);
    String qs = StrUtils.strjoinNL("PREFIX text:   <http://jena.apache.org/text#>", "PREFIX rdfs:   <http://www.w3.org/2000/01/rdf-schema#>", "SELECT *", "{ ?s a <http://example.org/Entity> . ?s text:query 'foo' }");
    Query q = QueryFactory.create(qs);
    QueryExecution qexec = QueryExecutionFactory.create(q, ds);
    ResultSet rs = qexec.execSelect();
    List<QuerySolution> x = Iter.toList(rs);
    ds.end();
    assertEquals(1, x.size());
}
